package cluster
import("testing";"time")
func TestSelectExcludesOfflineAndIncompatible(t *testing.T){r:=NewRegistry();now:=time.Now().UTC();r.Upsert(Node{NodeID:"ul7",Machine:"UL7",Online:true,LeaseUntil:now.Add(time.Minute),FreeWorkers:2,Capabilities:[]string{"bridge","blender"}});r.Upsert(Node{NodeID:"oda",Machine:"ODA",Online:true,LeaseUntil:now.Add(-time.Second),FreeWorkers:9,Capabilities:[]string{"comfyx"}});r.Upsert(Node{NodeID:"o87",Machine:"O87",Online:true,LeaseUntil:now.Add(time.Minute),FreeWorkers:3,Capabilities:[]string{"dwg"}});n,e:=r.Select("any",[]string{"bridge"});if e!=nil||n.NodeID!="ul7"{t.Fatalf("select=%+v err=%v",n,e)};if _,e=r.Select("any",[]string{"comfyx"});e==nil{t.Fatal("expired ODA lease must not route")}}
func TestSelectPrefersFreeWorkers(t *testing.T){r:=NewRegistry();until:=time.Now().UTC().Add(time.Minute);r.Upsert(Node{NodeID:"a",Machine:"A",LeaseUntil:until,FreeWorkers:1,Capabilities:[]string{"x"}});r.Upsert(Node{NodeID:"b",Machine:"B",LeaseUntil:until,FreeWorkers:4,Capabilities:[]string{"x"}});n,e:=r.Select("any",[]string{"x"});if e!=nil||n.NodeID!="b"{t.Fatalf("select=%+v err=%v",n,e)}}
